167	  /// The shared SSE-consumption step behind [sendMessage]/[retryMessage]
168	  /// (Code Map: "extract shared SSE buffer/parse helper") — buffers raw
169	  /// text from [chunks] until a full `\n\n`-terminated SSE event block is
170	  /// available, then hands each complete block to [_parseEvent].
171	  ///
172	  /// Terminal handling (Design Notes/I/O matrix):
173	  /// - An upstream `Left` (an offline/timeout/etc. failure from the
174	  ///   underlying HTTP call itself, surfaced by `ApiClient.postStream`) is
175	  ///   forwarded as-is and ends the stream immediately — covers "Send
176	  ///   while offline" (an immediate `Left(Failure.networkOffline)`, never
177	  ///   queued) and any other transport-level failure.
178	  /// - A parsed `done` event or an in-band `error` event (mapped via
179	  ///   [Failure.fromCode]) both end the stream right after being emitted
180	  ///   — the backend's own SSE ordering guarantees neither is followed by
181	  ///   anything else worth reading.
182	  /// - If the underlying byte stream simply ends (no exception, no
183	  ///   `done`/`error` event ever parsed) — a mid-stream drop — a single
184	  ///   trailing `Left(Failure.networkTimeout)` is emitted, since the
185	  ///   closed, 13-code taxonomy has no dedicated "dropped stream" code
186	  ///   (Design Notes).
187	  Stream<Either<Failure, ChatStreamEvent>> _consumeSse(
188	    Stream<Either<Failure, String>> chunks,
189	  ) async* {
190	    var buffer = '';
191	    await for (final chunkResult in chunks) {
192	      final upstreamFailure = chunkResult.fold((f) => f, (_) => null);
193	      if (upstreamFailure != null) {
194	        yield left(upstreamFailure);
195	        return;
196	      }
197	      final chunk = chunkResult.fold((_) => '', (s) => s);
198	      // Normalize after concatenation, not per-chunk — a `\r\n` line
199	      // ending split exactly across two chunks (one ends `\r`, the next
200	      // starts `\n`) would otherwise survive unnormalized in `buffer`.
201	      buffer = (buffer + chunk).replaceAll('\r\n', '\n');
202	
203	      var separatorIndex = buffer.indexOf('\n\n');
204	      while (separatorIndex != -1) {
205	        final rawEvent = buffer.substring(0, separatorIndex);
206	        buffer = buffer.substring(separatorIndex + 2);
207	        if (rawEvent.trim().isNotEmpty) {
208	          final parsed = _parseEvent(rawEvent);
209	          if (parsed != null) {
210	            final isDone = parsed.fold((_) => false, (e) => e is ChatDoneEvent);
211	            final isFailure = parsed.isLeft();
212	            yield parsed;
213	            // A `done`/in-band-error exit is a clean terminal event, not
214	            // a drop — return directly, skipping the trailing
215	            // mid-stream-drop failure below.
216	            if (isDone || isFailure) {
217	              return;
218	            }
219	          }
220	        }
221	        separatorIndex = buffer.indexOf('\n\n');
222	      }
223	    }
224	    // Reached only if the byte stream ended on its own (no exception, no
225	    // `done`/`error` event ever parsed) — a mid-stream drop.
226	    yield left(
227	      const Failure.networkTimeout(
228	        message: 'Connection closed before the response completed',
229	      ),
230	    );
231	  }
232	
233	  /// Parses one complete, blank-line-delimited SSE event block into a
234	  /// [ChatStreamEvent] (`Right`), an in-band failure (`Left`), or `null`
235	  /// when the block should simply be skipped — a `context` event
236	  /// (Boundaries: "received and discarded", never surfaced as a
237	  /// [ChatStreamEvent]) or any event name this client doesn't recognize
238	  /// (forward-compatible: an unknown future event type is ignored rather
239	  /// than treated as malformed). Any JSON-decode failure, or a decoded
240	  /// payload missing the field a known event name requires, maps to
241	  /// [Failure.malformedResponse] (Design Notes: "anything that fails to
242	  /// parse as expected becomes `Failure.malformedResponse`, never a
243	  /// crash") — never a thrown exception escaping into [sendMessage]'s own
244	  /// `async*` body.
245	  Either<Failure, ChatStreamEvent>? _parseEvent(String rawEvent) {
246	    String? eventName;
247	    final dataLines = <String>[];
248	    for (final line in rawEvent.split('\n')) {
249	      if (line.startsWith('event:')) {
250	        eventName = line.substring('event:'.length).trim();
251	      } else if (line.startsWith('data:')) {
252	        var value = line.substring('data:'.length);
253	        if (value.startsWith(' ')) {
254	          value = value.substring(1);
255	        }
256	        dataLines.add(value);
257	      }
258	    }
259	    if (eventName == null) {
260	      return null;
261	    }
262	    final dataStr = dataLines.join('\n');
263	
264	    switch (eventName) {
265	      case 'message_created':
266	        try {
267	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
268	          return right(ChatMessageCreatedEvent(json['id'] as String));
269	        } catch (error) {
270	          return left(
271	            Failure.malformedResponse(
272	              message: 'malformed message_created event: $error',
273	            ),
274	          );
275	        }
276	      case 'context':
277	        // Boundaries: "never rendering the SSE `context` event's
278	        // retrieval/citation data" — received and discarded.
279	        return null;
280	      case 'token':
281	        try {
282	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
283	          return right(ChatTokenEvent(json['delta'] as String));
284	        } catch (error) {
285	          return left(
286	            Failure.malformedResponse(
287	              message: 'malformed token event: $error',
288	            ),
289	          );
290	        }
291	      case 'done':
292	        return right(const ChatDoneEvent());
293	      case 'error':
294	        try {
295	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
296	          final code = json['code'] as String;
297	          final message = json['message'];
298	          return left(
299	            Failure.fromCode(
300	              code,
301	              message is String ? message : 'Unknown error',
302	            ),
303	          );
304	        } catch (error) {
305	          return left(
306	            Failure.malformedResponse(
307	              message: 'malformed error event: $error',
308	            ),
309	          );
310	        }
311	      default:
312	        // Forward-compatible: an event name this client doesn't
313	        // recognize is skipped, not treated as malformed.
314	        return null;
315	    }
316	  }
317	}
