291	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
292	    id: message.id,
293	    role: message.role,
294	    content: message.content,
295	    status: message.status,
296	    // spec-6-3 — every message reloaded from `chat-messages-list`/the
297	    // offline cache already has a persisted server id (unlike a message
298	    // created locally mid-session, which only gains one once/if
299	    // `message_created` arrives, Design Notes); [retryMessage] reads this
300	    // off the *user* message immediately preceding a `failed` AI bubble.
301	    serverId: message.id,
302	  );
303	
304	  /// Boundaries: optimistic user bubble, then subscribes to
305	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
306	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
307	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
308	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
309	  ///
310	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
311	  /// or failed — the composer is disabled in that case anyway), while
312	  /// [content] is blank once trimmed, or while [_isSending] is already
313	  /// true — this story never races two concurrent sends against the one
314	  /// in-memory session. Deliberately not keyed off any loaded message's
315	  /// persisted `streaming` status — a message restored from history/cache
316	  /// can legitimately carry that status without a send actually being in
317	  /// flight (I/O matrix: mid-stream drop).
318	  Future<void> sendMessage(String content) async {
319	    final trimmed = content.trim();
320	    if (trimmed.isEmpty) {
321	      return;
322	    }
323	    final current = state;
324	    if (current is! ChatReady) {
325	      return;
326	    }
327	    if (_isSending) {
328	      return;
329	    }
330	    _isSending = true;
331	
332	    final userMessage = ChatUiMessage(
333	      id: _nextLocalId(),
334	      role: ChatMessageRole.user,
335	      content: trimmed,
336	      status: ChatMessageStatus.complete,
337	    );
338	    final aiMessage = ChatUiMessage(
339	      id: _nextLocalId(),
340	      role: ChatMessageRole.assistant,
341	      content: '',
342	      status: ChatMessageStatus.streaming,
343	    );
344	    emit(
345	      current.copyWith(
346	        messages: [...current.messages, userMessage, aiMessage],
347	        isSending: true,
348	      ),
349	    );
350	
351	    await _consumeStream(
352	      _repository.sendMessage(current.sessionId, trimmed),
353	      userMessageId: userMessage.id,
354	      aiMessageId: aiMessage.id,
355	    );
356	  }
357	
358	  /// spec-6-3 — Boundaries: "Retry resets the *same* bubble (id,
359	  /// position) to `streaming`/empty, then reuses `_applyStreamEvent`/
360	  /// `_markFailed` unchanged — never a second bubble, never a duplicate
361	  /// question." [aiMessageId] must identify an existing `failed` AI
362	  /// bubble; anything else (not found, not `failed`, no preceding user
363	  /// message — shouldn't structurally happen) is a silent no-op, same
364	  /// defensive shape [sendMessage]'s own guards use.
365	  ///
366	  /// Keyed by the preceding user message's [ChatUiMessage.serverId]
367	  /// (Boundaries: "keyed by the user message's persisted id") — calls
368	  /// `ChatRepository.retryMessage` when it's known, or falls back to a
369	  /// full [ChatRepository.sendMessage] resend of that same user content
370	  /// into this exact AI bubble slot when it's `null` (I/O matrix: "Tap
371	  /// retry, no `serverId`" — the stream dropped before `message_created`
372	  /// ever arrived, so the backend never actually persisted the question;
373	  /// Boundaries: "Never calling `chat-messages-retry` with no `serverId`").
374	  /// Reuses [_isSending] verbatim (Boundaries: "A second retry while one
375	  /// is in flight"), so this is a no-op while a send/retry is already in
376	  /// flight.
377	  Future<void> retryMessage(String aiMessageId) async {
378	    final current = state;
379	    if (current is! ChatReady) {
380	      return;
381	    }
382	    if (_isSending) {
383	      return;
384	    }
385	    final messages = current.messages;
386	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
387	    if (aiIndex == -1 || messages[aiIndex].status != ChatMessageStatus.failed) {
388	      return;
389	    }
390	    ChatUiMessage? userMessage;
391	    for (var i = aiIndex - 1; i >= 0; i--) {
392	      if (messages[i].role == ChatMessageRole.user) {
393	        userMessage = messages[i];
394	        break;
395	      }
396	    }
397	    if (userMessage == null) {
398	      return;
399	    }
400	
401	    _isSending = true;
402	    emit(
403	      current.copyWith(
404	        messages: [
405	          for (final message in current.messages)
406	            if (message.id == aiMessageId)
407	              message.copyWith(content: '', status: ChatMessageStatus.streaming)
408	            else
409	              message,
410	        ],
411	        isSending: true,
412	      ),
413	    );
414	
415	    final serverId = userMessage.serverId;
416	    final stream = serverId == null
417	        ? _repository.sendMessage(current.sessionId, userMessage.content)
418	        : _repository.retryMessage(current.sessionId, serverId);
419	    await _consumeStream(
420	      stream,
421	      userMessageId: userMessage.id,
422	      aiMessageId: aiMessageId,
423	    );
424	  }
425	
426	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
427	  /// helper" extends to this subscribe-and-wait shape too, not just
428	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
429	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
430	  /// resolves once the stream ends (`done`, an in-band error, or a
431	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
432	  /// either way via [_finishSending].
433	  Future<void> _consumeStream(
434	    Stream<Either<Failure, ChatStreamEvent>> stream, {
435	    required String userMessageId,
436	    required String aiMessageId,
437	  }) async {
438	    await _sendSubscription?.cancel();
439	    final completer = Completer<void>();
440	    _sendCompleter = completer;
441	    _sendSubscription = stream.listen(
442	      (event) {
443	        event.match(
444	          (failure) => _markFailed(aiMessageId),
445	          (streamEvent) =>
446	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
447	        );
448	      },
449	      onError: (Object _, StackTrace _) {
450	        // RNF09: no exception escapes the cubit — a stream-level error
451	        // (shouldn't happen, `ChatRemoteDataSource` never lets one through
452	        // unmapped) still only fails the bubble, never crashes.
453	        _markFailed(aiMessageId);
454	        _finishSending();
455	        if (!completer.isCompleted) {
456	          completer.complete();
457	        }
458	        // Review finding: a stale, already-done subscription reference
459	        // left on `_sendSubscription` made a *later* send/retry's own
460	        // `await _sendSubscription?.cancel()` above hang indefinitely in
461	        // practice (observed via a widget test driving two sends back to
462	        // back) — cleared here (and in the `onDone` branch below)
463	        // exactly where this stream's own lifecycle actually ends,
464	        // rather than relying on cancelling an already-finished
465	        // subscription being an instant no-op.
466	        _sendSubscription = null;
467	        _sendCompleter = null;
468	      },
469	      onDone: () {
470	        _finishSending();
471	        if (!completer.isCompleted) {
472	          completer.complete();
473	        }
474	        _sendSubscription = null;
475	        _sendCompleter = null;
476	      },
477	      cancelOnError: false,
478	    );
479	    await completer.future;
480	  }
481	
482	  /// Clears both the internal re-entrancy guard and the UI-facing
483	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
484	  /// an in-band error, or a stream-level error) — the single place both
485	  /// flip back together.
486	  void _finishSending() {
487	    _isSending = false;
488	    if (isClosed) {
489	      return;
490	    }
491	    final current = state;
492	    if (current is ChatReady) {
493	      emit(current.copyWith(isSending: false));
494	    }
495	  }
496	
497	  void _applyStreamEvent(
498	    String userMessageId,
499	    String aiMessageId,
500	    ChatStreamEvent event,
501	  ) {
502	    if (isClosed) {
503	      return;
504	    }
505	    final current = state;
506	    if (current is! ChatReady) {
507	      return;
508	    }
509	    switch (event) {
510	      case ChatMessageCreatedEvent(userMessageId: final serverId):
511	        // spec-6-3 — Design Notes: "the persisted *user*-message id" is
512	        // now this story's first consumer, captured onto the matching
513	        // local user bubble by id so a later `retryMessage` call (on the
514	        // AI bubble this same send produces) has a non-null `serverId` to
515	        // key `chat-messages-retry` off of.
516	        emit(
517	          current.copyWith(
518	            messages: [
519	              for (final message in current.messages)
520	                if (message.id == userMessageId)
521	                  message.copyWith(serverId: serverId)
522	                else
523	                  message,
524	            ],
525	          ),
526	        );
527	      case ChatTokenEvent(delta: final delta):
528	        emit(
529	          current.copyWith(
530	            messages: [
531	              for (final message in current.messages)
532	                if (message.id == aiMessageId)
533	                  message.copyWith(content: message.content + delta)
534	                else
535	                  message,
536	            ],
537	          ),
538	        );
539	      case ChatDoneEvent():
540	        emit(
541	          current.copyWith(
542	            messages: [
543	              for (final message in current.messages)
544	                if (message.id == aiMessageId)
545	                  message.copyWith(status: ChatMessageStatus.complete)
546	                else
547	                  message,
548	            ],
549	          ),
550	        );
551	    }
552	  }
553	
554	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
555	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
556	  /// as-is (never cleared, Boundaries).
557	  void _markFailed(String aiMessageId) {
558	    if (isClosed) {
559	      return;
560	    }
561	    final current = state;
562	    if (current is! ChatReady) {
563	      return;
564	    }
565	    emit(
566	      current.copyWith(
567	        messages: [
568	          for (final message in current.messages)
569	            if (message.id == aiMessageId)
570	              message.copyWith(status: ChatMessageStatus.failed)
571	            else
572	              message,
573	        ],
574	      ),
575	    );
576	  }
577	
578	  String _nextLocalId() => 'local-${_localIdCounter++}';
579	
580	  /// spec-6-3 — [_connectivityWatcher]'s own listener: [isOnline] `true`
581	  /// means the device currently has connectivity. Always updates
582	  /// [_isOffline] (even outside [ChatReady] — see [_isOffline]'s own doc),
583	  /// but only *emits* when already [ChatReady] and the value actually
584	  /// changed, so an unrelated repeated emission of the same status (e.g.
585	  /// a plugin re-announcing "still online") never triggers a spurious
586	  /// rebuild.
587	  void _handleConnectivityChange(bool isOnline) {
588	    _isOffline = !isOnline;
589	    if (isClosed) {
590	      return;
591	    }
592	    final current = state;
593	    if (current is ChatReady && current.isOffline != _isOffline) {
594	      emit(current.copyWith(isOffline: _isOffline));
595	    }
596	  }
597	
598	  /// Review finding: "Cross-session stream leakage" — [switchSession]/
599	  /// [startNewSession] call this before touching anything else whenever
600	  /// they're about to make a *different* session active, so a response
601	  /// still streaming into the session being left behind can never go on
602	  /// to mutate the one that replaces it. Exactly [close]'s own cleanup
603	  /// below (cancel the subscription, resolve the stranded [sendMessage]
604	  /// caller, clear the re-entrancy guard), just without closing the cubit
605	  /// itself — a no-op when nothing is actually in flight.
606	  Future<void> _cancelInFlightSend() async {
607	    if (!_isSending) {
608	      return;
609	    }
610	    await _sendSubscription?.cancel();
611	    _sendSubscription = null;
612	    final completer = _sendCompleter;
613	    if (completer != null && !completer.isCompleted) {
614	      completer.complete();
615	    }
616	    _sendCompleter = null;
617	    _isSending = false;
618	  }
619	
620	  @override
621	  Future<void> close() {
622	    _connectivitySubscription?.cancel();
623	    _sendSubscription?.cancel();
624	    final completer = _sendCompleter;
625	    if (completer != null && !completer.isCompleted) {
626	      completer.complete();
627	    }
628	    _sendCompleter = null;
629	    return super.close();
630	  }
631	}
