13	/// The `chat_sessions`/`chat_messages` Hive box names — two boxes (Code
14	/// Map: "Hive box cache for `listSessions`/`listMessages`"), mirroring
15	/// `entries_injection.dart`'s `entriesBoxName` pattern but split in two
16	/// since each caches a structurally different DTO shape.
17	const chatSessionsBoxName = 'chat_sessions';
18	const chatMessagesBoxName = 'chat_messages';
19	
20	/// Registers the `chat` feature into the project's single `get_it`
21	/// instance (`sl`) — mirrors `entries_injection.dart`'s pattern. Called
22	/// from `setupCoreDependencies()` after `Hive.initFlutter()` has already
23	/// run (Code Map), same ordering requirement `registerEntriesFeature()`
24	/// documents for itself.
25	Future<void> registerChatFeature() async {
26	  final sessionsBox = await Hive.openBox<Map>(chatSessionsBoxName);
27	  final messagesBox = await Hive.openBox<Map>(chatMessagesBoxName);
28	  // `instanceName` disambiguates the two `Box<Map>` singletons from each
29	  // other and from `entries_injection.dart`'s own unnamed one — `get_it`
30	  // keys a registration by type + instance name, so three same-typed
31	  // singletons coexist safely.
32	  sl.registerSingleton<Box<Map>>(sessionsBox, instanceName: chatSessionsBoxName);
33	  sl.registerSingleton<Box<Map>>(messagesBox, instanceName: chatMessagesBoxName);
34	
35	  sl.registerLazySingleton<ChatRemoteDataSource>(
36	    () => ChatRemoteDataSource(sl<ApiClient>()),
37	  );
38	
39	  sl.registerLazySingleton<ChatRepository>(
40	    () => ChatRepositoryImpl(
41	      remoteDataSource: sl<ChatRemoteDataSource>(),
42	      sessionsBox: sl<Box<Map>>(instanceName: chatSessionsBoxName),
43	      messagesBox: sl<Box<Map>>(instanceName: chatMessagesBoxName),
44	    ),
45	  );
46	
47	  // spec-6-3 — one real `Connectivity`/`ConnectivityWatcher` for the
48	  // app's lifetime, mirroring `capture_injection.dart`'s own
49	  // `record_pkg.AudioRecorder`/`MicRecorder` registration shape.
50	  sl.registerLazySingleton<Connectivity>(Connectivity.new);
51	  sl.registerLazySingleton<ConnectivityWatcher>(
52	    () => ConnectivityPlusWatcher(connectivity: sl<Connectivity>()),
53	  );
54	
55	  // A `lazySingleton`, not a factory (Code Map), mirroring
56	  // `MeusRegistrosCubit`: long-lived, so a session bootstrapped on one
57	  // visit to Home/Chat survives leaving and returning within the same app
58	  // session (`ChatCubit.init()`'s own no-op guard). `dispose:` wires
59	  // `close()` into `get_it`'s own reset lifecycle, same convention every
60	  // other long-lived cubit in this codebase already uses.
61	  sl.registerLazySingleton<ChatCubit>(
62	    () => ChatCubit(sl<ChatRepository>(), sl<ConnectivityWatcher>()),
63	    dispose: (cubit) => cubit.close(),
64	  );
65	}
