1	import 'package:dio/dio.dart';
2	
3	import 'dio_error_code.dart';
4	import 'header_interceptor.dart';
5	
6	/// AD-4 — the one place retry policy lives. Retries only the 6 server
7	/// `retryable:true` codes (`error-taxonomy.md`); every other failure
8	/// (including the local `MalformedResponse`) surfaces once, unretried.
9	///
10	/// Design note (docs/input is silent on the schedule): fixed 500ms delay,
11	/// max 2 retries.
12	class RetryInterceptor extends Interceptor {
13	  RetryInterceptor(this._dio);
14	
15	  final Dio _dio;
16	
17	  /// The 6 server `retryable:true` codes — the only codes this interceptor
18	  /// ever retries.
19	  static const Set<String> retryableCodes = {
20	    'NETWORK_TIMEOUT',
21	    'NETWORK_OFFLINE',
22	    'PII_CHECK_FAILED',
23	    'EMBEDDING_FAILED',
24	    'AI_GENERATION_TIMEOUT',
25	    'RATE_LIMITED',
26	  };
27	
28	  /// Non-idempotent POSTs with no client-supplied idempotency key — a
29	  /// transparent retry here would silently resend the identical request
30	  /// (the same chat message content, or a second session-create) rather
31	  /// than surfacing the failure once to the caller. `dioErrorCodeOf` can
32	  /// return a retryable code for these from `DioException.type` alone
33	  /// (`NETWORK_TIMEOUT`/`NETWORK_OFFLINE`) even before any response body
34	  /// exists to carry the real `{code,message}`, so excluding by function
35	  /// name here is the only place this can be enforced.
36	  static const Set<String> neverRetriedFunctions = {
37	    'chat-messages-send',
38	    'chat-messages-retry',
39	    'chat-sessions-create',
40	  };
41	
42	  static const int maxRetries = 2;
43	  static const Duration retryDelay = Duration(milliseconds: 500);
44	
45	  static const _attemptKey = 'cerne_retry_attempt';
46	
47	  @override
48	  void onError(DioException err, ErrorInterceptorHandler handler) async {
49	    final attempt = attemptOf(err);
50	
51	    if (shouldRetry(err, attempt)) {
52	      await Future<void>.delayed(retryDelay);
53	      final options = err.requestOptions;
54	      options.extra[_attemptKey] = attempt + 1;
55	      try {
56	        final response = await _dio.fetch<dynamic>(options);
57	        handler.resolve(response);
58	      } on DioException catch (retryError) {
59	        handler.next(retryError);
60	      } catch (retryError) {
61	        // Any non-DioException thrown by the retried fetch must still reach
62	        // the caller through `handler`, never escape unhandled (RNF09).
63	        handler.next(
64	          DioException(
65	            requestOptions: options,
66	            error: retryError,
67	            type: DioExceptionType.unknown,
68	          ),
69	        );
70	      }
71	      return;
72	    }
73	
74	    handler.next(err);
75	  }
76	
77	  /// How many retries have already been attempted for this request.
78	  static int attemptOf(DioException err) =>
79	      (err.requestOptions.extra[_attemptKey] as int?) ?? 0;
80	
81	  /// The backend error `code` for [err] — delegates to the shared
82	  /// [dioErrorCodeOf] (also used by `ApiClient`) so a client-side timeout or
83	  /// a cancelled request is never misread as `NETWORK_OFFLINE` here.
84	  static String? errorCodeOf(DioException err) => dioErrorCodeOf(err);
85	
86	  /// Pure decision function, independently testable: retry only if the
87	  /// error's code is one of the 6 allowlisted codes, the max-retries
88	  /// budget isn't exhausted yet, and the request isn't one of the
89	  /// [neverRetriedFunctions].
90	  static bool shouldRetry(DioException err, int attempt) {
91	    final code = errorCodeOf(err);
92	    if (code == null || !retryableCodes.contains(code) || attempt >= maxRetries) {
93	      return false;
94	    }
95	    final function = HeaderInterceptor.functionNameOf(err.requestOptions.path);
96	    return !neverRetriedFunctions.contains(function);
97	  }
98	}
