1	import 'package:connectivity_plus/connectivity_plus.dart';
2	
3	import '../../domain/services/connectivity_watcher.dart';
4	
5	/// Wraps `package:connectivity_plus`'s `Connectivity` behind the
6	/// [ConnectivityWatcher] port — a `get_it` lazy singleton
7	/// (`chat_injection.dart`), mirroring `RecordMicRecorder`'s own
8	/// "wrap-the-real-plugin" shape.
9	///
10	/// [watch] emits the device's *current* status immediately on `listen()`
11	/// (via [Connectivity.checkConnectivity]), then every subsequent change
12	/// (via [Connectivity.onConnectivityChanged]) — so a caller that starts
13	/// out already offline (e.g. `ChatCubit`'s own constructor-time
14	/// subscription) learns that right away, not only once the status
15	/// changes for the first time. The initial read is best-effort: if the
16	/// underlying platform channel is unavailable (no device/simulator exists
17	/// yet, AGENTS.md) it's silently skipped rather than ending the stream —
18	/// the live [Connectivity.onConnectivityChanged] subscription below still
19	/// gets its own chance to work (or, under the same constraint, to end in
20	/// its own stream error, which `ChatCubit`'s subscription already handles,
21	/// RNF09).
22	class ConnectivityPlusWatcher implements ConnectivityWatcher {
23	  ConnectivityPlusWatcher({Connectivity? connectivity})
24	    : _connectivity = connectivity ?? Connectivity();
25	
26	  final Connectivity _connectivity;
27	
28	  @override
29	  Stream<bool> watch() async* {
30	    try {
31	      yield _isOnline(await _connectivity.checkConnectivity());
32	    } catch (_) {
33	      // Best-effort initial snapshot — see this class's own doc above.
34	    }
35	    yield* _connectivity.onConnectivityChanged.map(_isOnline);
36	  }
37	
38	  /// `connectivity_plus`'s own contract: the emitted list is never empty,
39	  /// and [ConnectivityResult.none] only ever appears alone (the package's
40	  /// own doc on `Connectivity.onConnectivityChanged`) — so "online" is
41	  /// simply "not exactly `[none]`", checked the permissive way (`any`
42	  /// non-`none` entry) rather than relying on that exact shape.
43	  static bool _isOnline(List<ConnectivityResult> results) =>
44	      results.any((result) => result != ConnectivityResult.none);
45	}
